"""Author the combat version of the chronicle without changing quest ids or completed saves."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
p=root/'Assets/AfterSignal/Resources/Story/CityChronicle.json'
data=json.loads(p.read_text(encoding='utf-8-sig'))
# title, field position, natural briefing, discovery, third phase
operations=[
('새벽을 빼앗긴 골목',(460,.1,2650),'은서가 있는 골목에 무장한 사람들이 들어왔어. 주민을 차에 태우고 있어. 지금 막아야 해.','은서: 서하, 고마워. 저 사람들 옷에 N-17이라고 쓰여 있었어. 우리 이름이 적힌 명단도 있었고.','rescue'),
('응급실 봉쇄',(365,.1,-260),'온유병원까지 회수대가 왔어. 부상자를 밖으로 끌어내고 있어. 구급차가 빠져나갈 길을 열어 줘.','한결: 치료 명령이 아니었어요. 환자의 기억을 지우라는 명령이었습니다. 원본을 당신에게 넘기죠.','defend'),
('중앙역 탈환',(85,.1,-120),'중앙역 출구가 봉쇄됐어. 주민들이 승강장에 갇혔어. 소거 장치를 부수면 문이 열려.','서하: 사람을 지우면서 도시를 지킨다고? 저 방송, 내가 끊어 버릴게.','escape'),
('강철 아래의 증언',(1340,.1,-337),'이곳 창고가 납치된 주민의 중간 수용소야. 경비를 뚫고 수송 명단을 확보하자.','생존자: 우릴 노바로 보내려 했어요. 기억을 연료처럼 쓸 수 있다고 했어요.','rescue'),
('첫 번째 균열',(1080,.1,70),'소거 장치가 폭주했어. 길 한가운데서 무언가 나와. 군 지원은 아직 멀어. 우리가 시간을 벌자.','노아: 저 괴물의 신호에서 주민들 이름이 잡혀. N-17이 사람들을 저렇게 만든 거야.','boss'),
('끊어진 출항 명령',(1700,.1,-560),'회수대가 마지막 증거를 배에 싣고 있어. 부두를 장악하기 전에 화물 통로부터 끊자.','항만 직원: 노바 측 수신 코드를 찾았습니다. N-17 본부는 해협 건너에 있어요.','escape'),
('노바의 환영 인사',(920,.1,-2450),'노바 경계에 도착했어. 이미 우리 이동을 알고 있어. 매복을 뚫고 민간 선박을 대피시켜.','서하: 환영이 거창하네. 그래도 돌아갈 생각 없어. 은서 이웃들이 아직 여기 있어.','defend'),
('유리 도시의 사냥꾼',(610,.1,-2850),'시장 지하 송신기가 주민 위치를 추적해. 장치를 부수면 회수대도 사람들을 못 찾아.','시장 상인: 우리를 지켜보던 눈이 꺼졌군. 연구소 직원이 당신을 기다려. 살아서 만나시오.','rescue'),
('연구원의 마지막 교대',(1360,.1,-2880),'해양연구소 직원이 증언하겠대. 정문에 저격조가 있어. 먼저 제압하고 연구원을 데리고 나와.','연구원: 소거는 실패한 기능이 아니에요. 처음부터 사람의 기억을 모으는 계획이었어요.','rescue'),
('폭풍 속 기록금고',(1610,.1,-3540),'원본 명령서가 이 금고에 있어. 방호 장치와 경비대를 뚫으면 누가 명령했는지 드러나.','노아: 도시기억관리청 승인 서명이다. 상부는 사고를 알고도 실험을 계속했어.','defend'),
('잠식의 문',(2820,.1,-45),'에레보스 관문이 무너졌어. 특수대가 포위됐어. 고립된 대원부터 구출하자.','격리대장: 시민을 구하러 갔다가 이렇게 됐소. 중앙 싱크홀 아래에서 계속 신호가 올라오오.','rescue'),
('침묵을 깨는 방송',(3250,.1,-623),'방송국에서 생존자 목소리가 들려. 회수대가 송출실을 불태우기 전에 들어가.','생존 방송원: 도시는 재난으로 무너진 게 아니에요. 주민 전원의 기억을 한 번에 빨아들였어요.','defend'),
('버려진 제7군',(2890,.1,-1728),'구 주둔지에 대형 잠식체가 자리 잡았어. 복원용 전력선을 막고 있어. 전차대가 진입할 길을 열자.','대원: 괴물 외피가 열릴 때 코어가 보인다. 그때 집중 사격해!','boss'),
('기억병원 구출전',(4120,.1,-532),'생존자들이 병원 지하에 있어. 발전기가 멈추면 문이 잠겨. 교전 중에도 전원을 지켜야 해.','간호사: 환자들이 같은 꿈을 꿔요. 바다 아래, 빛나는 도시에서 누군가 기다린대요.','rescue'),
('싱크홀의 심장',(3580,.1,-1290),'구덩이 가장자리에서 신호가 모이고 있어. 저 거신을 쓰러뜨려야 하부 기록망에 접속할 수 있어.','노아: 발신지는 네레이드야. 잠식된 사람들의 기억이 아직 거기 살아 있어.','boss'),
('심해 진입 작전',(3010,-61.8,-4420),'감압 관문을 회수대가 점거했어. 시민들이 바깥에 갇혔어. 통제 장치를 먼저 부숴.','관문 직원: 문이 열렸어요. 안으로 들어와요! 수압 격벽은 제가 맡을게요.','defend'),
('산호 정원의 총성',(3640,-61.8,-4170),'정원 대피소를 공격하고 있어. 주민들이 도망갈 시간을 벌어 줘. 여기까지 실험실로 만들 순 없어.','서하: 숨 쉬러 온 곳에서도 총을 피해야 하다니. 전부 끝내고 편하게 다시 오자.','rescue'),
('아틀라스의 진실',(4210,-61.8,-4240),'연구원들이 기억 원본을 지키고 있어. 회수대는 사람보다 기록을 먼저 파괴하려 할 거야.','연구원: 복원할 수 있어요. 다만 장치를 멈추는 순간 저들이 도시 전력을 끊을 겁니다.','defend'),
('블루 아카이브 방어전',(4410,-61.8,-5120),'복원 키를 추출하는 동안 이곳을 지켜 줘. 이제 심부름은 끝이야. 우리가 가진 건 그들의 약점이야.','노아: 키 확보! 원본은 시민 것이라는 증거까지 챙겼어. 이제 밖으로 나가자.','escape'),
('수압 아래의 거신',(4680,-61.8,-4730),'소거 장치가 마지막 잠식체를 깨웠어. 돔이 무너지기 전에 코어를 부숴야 해. 예고선을 피해!','서하: 바다도 도시도 사람을 버리지 않았어. 사람을 버린 건 저 명령 하나였지.','boss'),
('새벽으로 돌아오는 길',(460,.1,2650),'회수대가 네 이웃을 인질로 잡았어. 원본 키를 내놓으래. 은서가 시간을 벌고 있어. 서둘러.','은서: 네가 돌아올 줄 알았어. 여긴 우리 집이잖아. 저 사람들한테 내줄 수 없지.','rescue'),
('시민 대피선',(280,.1,-270),'회수대가 도시 출구를 끊으려 해. 대피 차량들이 빠져나갈 때까지 도로를 지켜.','운전기사: 마지막 버스 출발! 다 태웠어. 서하, 이제 너도 살아서 돌아와.','defend'),
('관리청 역습',(1270,.1,178),'관리청이 증거를 지우기 시작했어. 통신 증폭기 세 개를 끊으면 소거 명령도 멈춰.','노아: 삭제가 멈췄어. 지시한 사람들도 이제 책임을 피할 수 없어.','escape'),
('꺼지지 않는 신호',(700,.1,160),'복원 신호를 송출할 준비가 됐어. 적이 송신 구역을 포위했어. 여기서 밀리면 모든 걸 잃어.','서하: 이름을 지우면 아무 일도 없던 게 된다고 생각했지? 우리가 여기 있다는 걸 보여 주자.','defend'),
('노바 최후 방어선',(1660,.1,-6430),'노바에서도 소거 명령이 살아 있어. 현지 경찰이 합류했어. 마지막 지휘조를 끌어내자.','노바 대장: 뒤는 우리가 지키겠소. 시민에게 총구를 돌린 자들은 더 이상 우리 동료가 아니오.','defend'),
('지휘망 절단',(480,.1,-6070),'방위사령부의 구형 통신망이 명령을 중계해. 오염된 경비대를 뚫고 송신 전력을 끊어.','노아: 모든 도시의 회수 명령이 끊겼어. 남은 건 에레보스 공명로 하나야.','escape'),
('잊힌 이름의 성당',(4510,.1,-1275),'기록성당에 원본 기억이 모여 있어. 소거대가 마지막 증거를 지키는 사람들을 쫓고 있어.','기록관: 죽은 줄 알았던 이름들이 돌아오고 있소. 더는 혼자 기억할 필요가 없겠구려.','rescue'),
('영점 공명로 돌파',(3670,.1,-1720),'반응로가 과부하 직전이야. 회수대 잔당과 잠식체가 동시에 몰려와. 제어선부터 끊자.','노아: 코어 외피가 열렸다. 이게 마지막 기회야. 서하, 네 목소리는 아직 들려.','boss'),
('마지막 밤의 수호자',(3900,.1,-1850),'공명로를 지키던 마지막 거신이 나왔어. 지금 후퇴하면 복원 신호가 끊겨. 마지막으로 버텨 줘.','서하: 들려? 은서도, 사라졌던 사람들도. 다들 집에 가자고 말하고 있어.','boss'),
('우리의 내일',(3960,-61.8,-4680),'복원 키를 시민에게 넘길 시간이야. 마지막 회수대가 몰려와. 이 광장을 지키고 결정을 끝내자.','은서: 오늘은 누가 없어질지 무서워하며 잠들지 않아도 되겠지? 서하: 응. 내일은 우리가 정하는 거야.','defend')]
modes={'assault':'회수대 돌파','sabotage':'소거 증폭기 3개 파괴','rescue':'생존자 구출 및 호위','defend':'대피 통로 방어','escape':'추격대 격파 후 탈출','boss':'대형 잠식체 격파'}
main=[q for q in data['quests'] if q['main']]
for i,(q,op) in enumerate(zip(main,operations)):
 title,pos,line,discovery,last=op;q['title']=title;q['arc']=f'{i//5+1}막 · '+['빼앗긴 새벽','해협의 추적자','잠식된 증거','심해의 이름들','도시의 반격','우리가 되찾는 내일'][i//5];q['summary']=line;q['reward']=500+i*80
 q['steps']=[]
 for phase,mode in enumerate(['assault','sabotage' if i%2==0 else 'defend',last]):
  p2=dict(zip(['x','y','z'],pos));p2['x']+=phase*4
  q['steps'].append(dict(site=0,world=True,position=p2,kind='battle',person='노아' if phase!=1 else '서하',label=modes[mode],line=line if phase==0 else '눈앞의 소거 장치부터 끊자. 경비대가 다시 오기 전에!' if mode=='sabotage' else '뒤에서 주민들이 빠져나가고 있어. 이 자리를 지켜야 해.' if mode=='defend' else '거신의 몸이 열릴 때 빛나는 기관을 노려. 공격 예고가 보이면 피하고!' if mode=='boss' else '길은 열었어. 남은 사람들을 데리고 집결점으로 가자.',outro=discovery if phase==2 else '노아: 첫 방어선을 뚫었어. 근처에서 다음 목표를 확인해.' if phase==0 else '서하: 소거 명령은 막았어. 이제 사람들을 지키자.',battleMode=mode,waves=1 if mode=='boss' else 2 if i>2 else 1,enemyCount=4+min(2,i//10),duration=35+min(25,i)))
p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Combat operations:',len(operations),'phases:',len(operations)*3)
